const (
	testImageA = "ocid1.image.oc1.sa-saopaulo-1.imagea"
	testImageB = "ocid1.image.oc1.sa-saopaulo-1.imageb"
)

// hostImage signs a release image receipt for imageID in environment with
// the fixture's leaf, under a root delegation for those images, valid from
// testNow for lifetime.
func (f fixture) hostImage(t *testing.T, imageID, environment string, root ed25519.PrivateKey, lifetime time.Duration) HostImage {
	t.Helper()
	keyID, err := trust.KeyID(f.leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	public, err := trust.EncodeDelegatedPublicKey(f.leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	revision := "0123456789abcdef0123456789abcdef01234567"
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID,
		SubjectPublicKey: public, Capabilities: []trust.Capability{{Domain: release.ImageDomain, DeploymentID: entityid.Derive("build", revision),
			Cell: "GRU", Environment: environment, Role: "oci-image", Slots: []string{imageID}, Actions: []string{"sign"}}},
	}, testNow.Add(-time.Minute), testNow.Add(lifetime), root)
	if err != nil {
		t.Fatal(err)
	}
	digest := strings.Repeat("ab", 32)
	payload := release.ImageReceipt{
		Schema: release.ImageSchema, SourceRevision: revision, GoVersion: release.DefaultGoVersion,
		Architecture: "arm64", BinaryBytes: 100, BinarySHA256: digest, QualificationSHA256: digest,
		BaseImageOCID: "ocid1.image.oc1.sa-saopaulo-1.base", BaseImageRegion: "GRU", BaseImageSHA256: digest,
		KernelRelease: "6.1.0-test+1", KernelSHA256: digest, ImageFormat: "qcow2", ImageBytes: 1024,
		ImageSHA256: digest, OCIImageOCID: imageID, OCIRegion: "GRU",
	}
	payload = qualifyHostImageFixture(t, payload, environment, root, testNow, lifetime)
	receipt, err := release.SignImageReceipt(payload, environment, delegation, f.roots, f.leafPrivate, testNow, lifetime)
	if err != nil && root.Equal(f.rootPrivate) {
		t.Fatal(err)
	}
	if err != nil {
		// SignImageReceipt refuses a delegation from another key; sign the
		// same receipt directly so verification is the only gate.
		encoded, encodeErr := trust.EncodePayload(payload)
		if encodeErr != nil {
			t.Fatal(encodeErr)
		}
		if receipt, err = trust.Sign(encoded, release.ImageScope(payload, environment), testNow, testNow.Add(lifetime), f.leafPrivate); err != nil {
			t.Fatal(err)
		}
	}
	return HostImage{ImageID: imageID, Receipt: encodeEnvelope(t, receipt), Delegation: encodeEnvelope(t, delegation)}

func qualifyHostImageFixture(t *testing.T, image release.ImageReceipt, environment string, root ed25519.PrivateKey, at time.Time, lifetime time.Duration) release.ImageReceipt {
	t.Helper()
	record := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: image.SourceRevision, ArtifactSHA256: image.ImageSHA256,
			QualificationSHA256: image.QualificationSHA256, Cell: image.OCIRegion, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: image.Architecture, Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " image evidence")
		evidenceDigest := sha256.Sum256(evidence)
		record.Evidence = append(record.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: hex.EncodeToString(evidenceDigest[:]), Bytes: int64(len(evidence)), CompletedAt: at.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(record)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(record.Candidate), at, at.Add(lifetime), root)
	if err != nil {
		t.Fatal(err)
	}
	image.Production = &release.ProductionProof{Qualification: encodeEnvelope(t, proof)}
	return image
}

func VerifyHostImages(previous, next Spec, roots trust.Keyring, now *time.Time) error {
	for _, image := range next.HostImages {
		expected := release.ImageExpectation{Environment: next.Environment,
			LogicalRegion: next.logicalRegion(), OCIImageOCID: image.ImageID}
		var err error
		if now == nil {
			_, err = release.VerifyImageHistorical(image.Receipt, image.Delegation, roots, expected)
		} else if before, kept := previous.HostImage(image.ImageID); !kept || !reflect.DeepEqual(before, image) ||
			image.ImageID == next.LaunchImage && next.LaunchImage != previous.LaunchImage {
			_, err = release.VerifyImageCurrent(image.Receipt, image.Delegation, roots, expected, *now)
		}
		if err != nil {
			return fmt.Errorf("host image %s is not qualified: %w", image.ImageID, err)
		}
	}
	return nil
}

func (receipt ImageReceipt) Validate() error {
	if receipt.Schema != ImageSchema || !revisionPattern.MatchString(receipt.SourceRevision) ||
		receipt.GoVersion != DefaultGoVersion || receipt.BinaryBytes <= 0 || receipt.BinaryBytes > MaxArtifactBytes ||
		!digestPattern.MatchString(receipt.BinarySHA256) || !digestPattern.MatchString(receipt.QualificationSHA256) ||
		!ValidRegion(receipt.BaseImageRegion) ||
		!ValidOCIImageIDForRegion(receipt.BaseImageOCID, receipt.BaseImageRegion) || !digestPattern.MatchString(receipt.BaseImageSHA256) ||
		!validKernelRelease(receipt.KernelRelease) || !digestPattern.MatchString(receipt.KernelSHA256) || receipt.ImageFormat != "qcow2" ||
		receipt.ImageBytes <= 0 || !digestPattern.MatchString(receipt.ImageSHA256) ||
		!ValidRegion(receipt.OCIRegion) || !ValidOCIImageIDForRegion(receipt.OCIImageOCID, receipt.OCIRegion) ||
		receipt.BaseImageRegion != receipt.OCIRegion {
		return fmt.Errorf("%w: image source, OCI scope, base image, kernel, format, size, or digest", ErrInvalidReceipt)
	}
	if receipt.Architecture != "amd64" && receipt.Architecture != "arm64" {
		return fmt.Errorf("%w: unsupported image architecture", ErrInvalidReceipt)
	}
	return nil
}

func ImageScope(receipt ImageReceipt, environment string) trust.Scope {
	return trust.Scope{
		Domain: ImageDomain, DeploymentID: entityid.Derive("build", receipt.SourceRevision), Cell: receipt.OCIRegion,
		Environment: environment, Role: "oci-image", Slot: receipt.OCIImageOCID,
	}
}

func SignImageReceipt(receipt ImageReceipt, environment string, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := validateEnvironment(environment); err != nil {
		return trust.Envelope{}, err
	}
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and at most %s", MaxReceiptLifetime)
	}
	productionExpiry, err := verifyImageProduction(receipt, environment, roots, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if validFor > 0 && productionExpiry.Before(now.Add(validFor)) {
		validFor = productionExpiry.Sub(now)
	}
	return signReceipt(receipt, ImageScope(receipt, environment), delegation, roots, privateKey, now, validFor)
}

func VerifyImageCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation, now time.Time,
) (VerifiedImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return VerifiedImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return VerifiedImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return VerifiedImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current signed image receipt: %w", err)
	}
	productionExpiry, err := verifyImageProduction(receipt, expected.Environment, roots, now)
	if err != nil {
		return VerifiedImage{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedImage{}, err
	}
	if productionExpiry.Before(proof.expiresAt) {
		proof.expiresAt = productionExpiry
	}
	return VerifiedImage{receipt: receipt, proof: proof}, nil
}

// VerifyImageHistorical verifies an image receipt's signature, issuance-time
// delegation, scope, and identity. Its distinct result is audit evidence only.
func VerifyImageHistorical(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation,
) (HistoricalImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return HistoricalImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return HistoricalImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return HistoricalImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return HistoricalImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return HistoricalImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationHistorical(delegationEnvelope, roots, delegationPolicy())
	if err != nil {
		return HistoricalImage{}, fmt.Errorf("verify historical release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedHistorical(envelope, scope, delegation, receiptPolicy()); err != nil {
		return HistoricalImage{}, fmt.Errorf("verify historical signed image receipt: %w", err)
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return HistoricalImage{}, err
	}
	return HistoricalImage{receipt: receipt, proof: proof}, nil
}

func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}

func decodeEnvelopePair(envelopeWire, delegationWire []byte) (trust.Envelope, trust.Envelope, error) {
	envelope, err := trust.DecodeEnvelope(envelopeWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, err
	}
	delegation, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, fmt.Errorf("decode release delegation: %w", err)
	}
	return envelope, delegation, nil
}

func decodeCanonicalPayload[T any](encoded []byte) (T, error) {
	var value T
	if len(encoded) == 0 || len(encoded) > trust.MaxPayloadBytes {
		return value, fmt.Errorf("%w: receipt payload size", ErrInvalidReceipt)
	}
	if err := protocol.DecodeStrict(encoded, &value, trust.MaxPayloadBytes); err != nil {
		return value, fmt.Errorf("decode release receipt payload: %w", err)
	}
	canonical, err := trust.EncodePayload(value)
	if err != nil {
		return value, err
	}
	if !bytes.Equal(canonical, encoded) {
		return value, fmt.Errorf("%w: payload is not canonical JSON", ErrInvalidReceipt)
	}
	return value, nil
}

func proofFor(envelope trust.Envelope) (receiptProof, error) {
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return receiptProof{}, err
	}
	if !digestPattern.MatchString(fingerprint) {
		return receiptProof{}, fmt.Errorf("%w: canonical envelope fingerprint", ErrInvalidReceipt)
	}
	return receiptProof{
		envelopeSHA256: fingerprint, keyID: envelope.KeyID,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

func delegationPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxDelegationLifetime, ClockSkew: clockSkew}
}

func receiptPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxReceiptLifetime, ClockSkew: clockSkew}
}

func validateEnvironment(environment string) error {
	if !ValidEnvironment(environment) {
		return fmt.Errorf("%w: unsupported environment", ErrInvalidReceipt)
	}
	return nil
}

func validateImageExpectation(expected ImageExpectation) error {
	if err := validateEnvironment(expected.Environment); err != nil {
		return err
	}
	if !ValidRegion(expected.LogicalRegion) {
		return fmt.Errorf("%w: unsupported logical image region", ErrInvalidReceipt)
	}
	if expected.OCIImageOCID != "" && !ValidOCIImageIDForRegion(expected.OCIImageOCID, expected.LogicalRegion) {
		return fmt.Errorf("%w: expected image OCID is invalid for logical region", ErrExpectationMismatch)
	}
	if expected.Architecture != "" && expected.Architecture != "amd64" && expected.Architecture != "arm64" {
		return fmt.Errorf("%w: expected image architecture is not a receipt architecture", ErrExpectationMismatch)
	}
	return nil
}

func matchImageExpectation(receipt ImageReceipt, expected ImageExpectation) error {
	if receipt.OCIRegion != expected.LogicalRegion || expected.OCIImageOCID != "" && receipt.OCIImageOCID != expected.OCIImageOCID ||
		expected.Architecture != "" && receipt.Architecture != expected.Architecture {
		return ErrExpectationMismatch
	}
	return nil
}

func oracleRegion(region string) string {
	return catalog.OCIRegion(region)
}

func validKernelRelease(value string) bool {
	if value == "" || len(value) > 128 {
		return false
	}
	for _, character := range value {
		if !(character >= 'a' && character <= 'z' || character >= 'A' && character <= 'Z' ||
			character >= '0' && character <= '9' || strings.ContainsRune("._+-", character)) {
			return false
		}
	}
	return true
}

func verifyImageProduction(receipt ImageReceipt, environment string, roots trust.Keyring, now time.Time) (time.Time, error) {
	if receipt.Production == nil {
		return time.Time{}, fmt.Errorf("%w: signed image contains no independent qualification", ErrProductionQualification)
	}
	expected := ProductionExpectation{SourceRevision: receipt.SourceRevision, ArtifactSHA256: receipt.ImageSHA256,
		QualificationSHA256: receipt.QualificationSHA256, Cell: receipt.OCIRegion, Environment: environment,
		Runtime: ProductionRuntime, Architecture: receipt.Architecture, Role: "orchestrator"}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots, expected, now); err != nil {
		return time.Time{}, err
	}
	envelope, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return time.Time{}, err
	}
	expires := envelope.ExpiresAt
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return time.Time{}, err
		}
		if delegation.ExpiresAt.Before(expires) {
			expires = delegation.ExpiresAt
		}
	}
	return expires, nil
}

func ProductionQualificationScope(candidate ProductionExpectation) trust.Scope {
	return trust.Scope{Domain: ProductionQualificationDomain, DeploymentID: entityid.Derive("build", candidate.SourceRevision),
		Cell: candidate.Cell, Environment: candidate.Environment, Role: candidate.Role,
		Slot: candidate.Runtime + "/linux-" + candidate.Architecture}
}

// VerifyProductionCurrent accepts a trusted root or an explicitly delegated
// qualification signer. An ordinary binary-release delegation grants no authority.
// The caller must also verify the referenced retained evidence bytes.
func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

